import 'dart:io';

import 'package:path/path.dart' as p;

import '../../common/pubspec_lock.dart';
import '../../init/expected.dart';
import '../../init/generated_files.dart';
import '../../init/targets.dart';
import '../config.dart';
import '../context.dart';
import '../rule.dart';
import '../suppression.dart';

/// R8：生成物（toolkit / AGENTS 片段）由旧版 w_tools_cli 生成。
///
/// 生成物头部带 `generated by w_tools_cli x.y.z`；与 pubspec.lock 里的实际版本
/// 不一致时提示重新运行 init。
class R8GeneratedStale {
  static const id = 'R8';
  static const title = '生成物版本';

  static final _version = RegExp(
    r'(?:generated by|由)\s*`?w_tools_cli`?\s*v?([0-9]+\.[0-9]+\.[0-9]+)',
    caseSensitive: false,
  );

  static DoctorRuleResult check(ProjectContext ctx, DoctorConfig config) {
    String? installed;
    try {
      installed = readLockedVersions(ctx.root)['w_tools_cli'];
    } on PubspecLockException catch (e) {
      return DoctorRuleResult(
        ruleId: id,
        title: title,
        status: DoctorRuleStatus.fail,
        issues: <DoctorIssue>[
          DoctorIssue(
            rule: id,
            level: DoctorLevel.warn,
            file: 'pubspec.lock',
            message: e.message,
            hint: '修复 pubspec.lock 后重跑 doctor',
          ),
        ],
      );
    }
    if (installed == null) {
      return const DoctorRuleResult(
        ruleId: id,
        title: title,
        status: DoctorRuleStatus.skipped,
        skipReason: 'pubspec.lock 里没有 w_tools_cli（未作为 dev_dependency 安装）',
      );
    }

    final files = GeneratedFiles.versioned(
      toolkitEntry: config.toolkitEntry,
      targets: targetFiles.keys,
    );
    // 有 .w_tools/init.json 才能回放生成内容；老项目 return null → 退回版本比对。
    final expectedArtifacts = ExpectedArtifacts.render(ctx.root);
    final issues = <DoctorIssue>[];
    var checked = 0;

    for (final rel in files) {
      final file = File(p.join(ctx.root.path, rel));
      if (!file.existsSync()) continue;
      final content = file.readAsStringSync();
      if (Suppression.isFileIgnored(content.split('\n'), id)) continue;
      // 用户自己写的 CLAUDE.md / copilot 文件不应该被当成生成物
      if (rel != config.toolkitEntry &&
          rel != GeneratedFiles.aiPrompts &&
          !content.contains('<!-- w_tools:begin -->')) {
        continue;
      }
      checked++;
      final match = _version.firstMatch(content);
      // 能回放生成内容就比内容：CLI 升版本但模板没变时不该报警。
      final expected = expectedArtifacts?[rel];
      if (expected != null) {
        if (_comparable(content) == _comparable(expected)) continue;
        issues.add(
          DoctorIssue(
            rule: id,
            level: DoctorLevel.warn,
            file: rel,
            message: match == null
                ? '生成物缺少 w_tools_cli 版本标记'
                : match.group(1) == installed
                ? '内容与 w_tools_cli $installed 的模板不同（可能被手改过）'
                : '由 w_tools_cli ${match.group(1)} 生成，内容与当前安装的 $installed 模板不同',
            hint: '运行 dart run w_tools_cli:w_tools init --force 刷新生成物（先看 --check-drift 的差异）',
            fix: DoctorFix.run('dart run w_tools_cli:w_tools init --force'),
          ),
        );
        continue;
      }
      if (match == null) {
        issues.add(
          DoctorIssue(
            rule: id,
            level: DoctorLevel.warn,
            file: rel,
            message: '生成物缺少 w_tools_cli 版本标记',
            hint: '运行 dart run w_tools_cli:w_tools init --force 重新生成',
            fix: DoctorFix.run('dart run w_tools_cli:w_tools init --force'),
          ),
        );
        continue;
      }
      final generatedBy = match.group(1)!;
      if (generatedBy != installed) {
        issues.add(
          DoctorIssue(
            rule: id,
            level: DoctorLevel.warn,
            file: rel,
            message: '由 w_tools_cli $generatedBy 生成，当前安装的是 $installed',
            hint: '运行 dart run w_tools_cli:w_tools init --force 刷新生成物（先看 --check-drift 的差异）',
            fix: DoctorFix.run('dart run w_tools_cli:w_tools init --force'),
          ),
        );
      }
    }

    if (checked == 0) {
      return const DoctorRuleResult(
        ruleId: id,
        title: title,
        status: DoctorRuleStatus.skipped,
        skipReason: '没有可检查的生成物',
      );
    }

    return DoctorRuleResult(
      ruleId: id,
      title: title,
      status: issues.isEmpty ? DoctorRuleStatus.pass : DoctorRuleStatus.fail,
      issues: issues,
    );
  }

  /// 只比「生成物本体」：标记块内是生成内容，块外是项目自己的东西。
  /// 没有标记块（AI_PROMPTS）时比整份文件。
  static String _comparable(String text) {
    final body = _markerBody(text) ?? text.trim();
    // 版本号本身不算漂移：模板没变、只是 CLI 打了新版本时不该报警。
    return body.replaceAllMapped(
      RegExp(r'(w_tools_cli`?\s*v?)[0-9]+\.[0-9]+\.[0-9]+'),
      (m) => '${m.group(1)}<version>',
    );
  }

  static String? _markerBody(String text) {
    const begins = <String>['<!-- w_tools:begin -->', '// w_tools:begin'];
    const ends = <String>['<!-- w_tools:end -->', '// w_tools:end'];
    for (final begin in begins) {
      final b = text.indexOf(begin);
      if (b < 0) continue;
      for (final end in ends) {
        final e = text.indexOf(end, b + begin.length);
        if (e > b) return text.substring(b + begin.length, e).trim();
      }
    }
    return null;
  }
}
